  void Awake(){Application.targetFrameRate=60;QualitySettings.vSyncCount=0;QualitySettings.skinWeights=SkinWeights.FourBones;QualitySettings.pixelLightCount=12;QualitySettings.shadowResolution=ShadowResolution.High;QualitySettings.shadows=ShadowQuality.All;QualitySettings.shadowDistance=15;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.32f,.34f,.4f);RenderSettings.ambientEquatorColor=new Color(.24f,.26f,.31f);RenderSettings.ambientGroundColor=new Color(.17f,.17f,.2f);font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","Segoe UI"},15);cloth=Resources.Load<ComputeShader>("Garment");logo=Resources.Load<Texture2D>("logo");camera=new GameObject("Native viewport").AddComponent<Camera>();camera.allowHDR=true;camera.allowMSAA=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.075f,.083f,.11f);camera.nearClipPlane=.01f;camera.farClipPlane=200;camera.fieldOfView=35;post=camera.gameObject.AddComponent<NativePost>();backdrop=camera.gameObject.AddComponent<NativeBackdrop>();key=new GameObject("Soft key").AddComponent<Light>();key.type=LightType.Directional;key.transform.rotation=Quaternion.Euler(40,-25,0);key.intensity=.88f;key.shadows=LightShadows.Soft;key.shadowStrength=.32f;key.shadowBias=.03f;key.shadowNormalBias=.15f;audio=gameObject.AddComponent<AudioSource>();audio.playOnAwake=false;ground=GameObject.CreatePrimitive(PrimitiveType.Plane);ground.name="Ground";ground.transform.localScale=Vector3.one;ground.GetComponent<Renderer>().sharedMaterial=new Material(Shader.Find("Standard")){color=new Color(.08f,.09f,.12f)};
