  void LoadSong(){string song=((string)songs[songIndex]["id"]).Substring(0,8);var mapping=layouts["songs"]?[song]??layouts["layouts"]?[song]??layouts[song];for(int role=0;role<5;role++){sourceSlots[role]=(int?)(mapping?["sourceSlots"]?[role])??role+1;if(actors[role]==null&&multi){int saved=selected;selected=role;ChoosePerson(role%people.Count);selected=saved;}if(actors[role]!=null){actors[role].motion=new NativeMotion(song+"-"+sourceSlots[role]);if(!move)placements[role]=actors[role].motion.InitialPosition();}}authored?.Dispose();authored=new NativeCamera(song);duration=(float)songs[songIndex]["duration"]*30;frame=0;foreach(var actor in actors.Where(a=>a!=null))foreach(var c in actor.cloth)c.ResetState();StartCoroutine(LoadAudio(song));message="原游戏五人动作和相机已加载";}
  IEnumerator LoadAudio(string song){var list=NativeAssets.Json("web/data/game-audio.json");var tracks=(JArray)(list["tracks"]??list["audio"]??list["songs"]);var found=tracks?.FirstOrDefault(t=>((string)t["id"]??"")==song||((string)t["songId"]??"")==song);if(found==null)yield break;using(var request=UnityWebRequestMultimedia.GetAudioClip(new Uri(NativeAssets.Local((string)found["url"])).AbsoluteUri,AudioType.OGGVORBIS)){yield return request.SendWebRequest();if(request.result==UnityWebRequest.Result.Success){audio.clip=DownloadHandlerAudioClip.GetContent(request);message="舞蹈与音频已就绪";}}}
  void Update(){ground.SetActive(stage==null&&backdrop.image==null&&!green);if(backdrop.image!=null)backdrop.enabled=!green;camera.rect=busy?new Rect(0,0,1,1):new Rect(255f/Screen.width,165f/Screen.height,Mathf.Max(.1f,(Screen.width-535f)/Screen.width),Mathf.Max(.1f,(Screen.height-225f)/Screen.height));if(playing&&!busy){frame+=Time.deltaTime*30;if(frame>duration){frame=0;if(audio.clip)audio.time=0;}if(audio.isPlaying)frame=audio.time*30;}Apply();if(!(cameraPreview&&(playing||busy)&&authored!=null)){camera.usePhysicalProperties=false;camera.orthographic=false;if(Input.GetMouseButton(1)&&Input.mousePosition.x>255&&Input.mousePosition.x<Screen.width-280){yaw+=Input.GetAxis("Mouse X")*3;pitch=Mathf.Clamp(pitch-Input.GetAxis("Mouse Y")*2,-40,70);}if(Input.mousePosition.x>255&&Input.mousePosition.x<Screen.width-280)distance=Mathf.Clamp(distance-Input.mouseScrollDelta.y*.18f,1,25);Quaternion q=Quaternion.Euler(pitch,yaw,0);camera.transform.position=new Vector3(0,.9f,0)+q*new Vector3(0,0,distance);camera.transform.LookAt(new Vector3(0,.9f,0));}if(Input.GetKeyDown(KeyCode.Space)&&!busy)Play();if(Input.GetKeyDown(KeyCode.LeftArrow))Seek(frame-1);if(Input.GetKeyDown(KeyCode.RightArrow))Seek(frame+1);}
  void Apply(){for(int role=0;role<5;role++){var actor=actors[role];if(actor==null)continue;actor.root.gameObject.SetActive(multi||role==selected);actor.motion?.Apply(actor,frame);
