    foreach(var pair in keys.Where(k=>k.Key.StartsWith(role+"/"))){string name=pair.Key.Substring(2);if(actor.bones.TryGetValue(name,out var bone)){var before=pair.Value.LastOrDefault(k=>k.Key<=frame);var after=pair.Value.FirstOrDefault(k=>k.Key>=frame);if(before.Value!=default(Quaternion)){bone.localRotation=after.Value!=default(Quaternion)&&after.Key>before.Key?Quaternion.Slerp(before.Value,after.Value,(frame-before.Key)/(after.Key-before.Key)):before.Value;}}}if(editingPose&&!playing&&role==selected&&actor.bones.TryGetValue(boneName,out var editTarget))editTarget.localRotation=Quaternion.Euler(editAngles);actor.Attachments();foreach(var c in actor.cloth){c.active=physics;c.strength=strength;}}
