  void OnGUI(){GUI.skin.font=font;GUI.skin.label.fontSize=14;GUI.skin.button.fontSize=14;GUI.skin.box.fontSize=14;GUI.color=new Color(.88f,.9f,.96f);GUI.Box(new Rect(0,0,Screen.width,60),"");if(logo)GUI.DrawTexture(new Rect(14,8,64,44),logo,ScaleMode.ScaleToFit);GUI.Label(new Rect(90,9,440,28),"22/7 MOTION STUDIO · UNITY NATIVE");GUI.Label(new Rect(90,32,430,20),"原生 GPU 渲染 · "+Version);GUILayout.BeginArea(new Rect(Screen.width-610,12,600,40));GUILayout.BeginHorizontal();if(GUILayout.Button("新建工程"))Guard(NewProject);if(GUILayout.Button("打开工程"))Guard(OpenProject);if(GUILayout.Button("保存工程"))Guard(SaveProject);if(GUILayout.Button("截图"))Guard(()=>StartCoroutine(Screenshot()));if(GUILayout.Button("MP4"))Guard(()=>StartCoroutine(Video()));if(GUILayout.Button("GitHub 更新"))StartCoroutine(CheckUpdate());GUILayout.EndHorizontal();GUILayout.EndArea();
