  void Preset(){post.exposure=.98f;post.bloom=.06f;post.tint=Color.white;key.color=Color.white;RenderSettings.fog=preset>0;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.012f;if(preset==1){key.color=new Color(.78f,.84f,1);post.tint=new Color(.97f,.98f,1);RenderSettings.fogColor=new Color(.15f,.17f,.23f);}if(preset==2){key.color=new Color(1,.9f,.8f);RenderSettings.fogColor=new Color(.23f,.2f,.19f);}if(preset==3){key.color=new Color(1,.92f,.95f);post.tint=new Color(1,.98f,.99f);RenderSettings.fogColor=new Color(.24f,.19f,.23f);}}
  void Particles(){if(particles)Destroy(particles.gameObject);if(!particleOn)return;particles=new GameObject("Native particles").AddComponent<ParticleSystem>();particles.transform.position=new Vector3(0,2.7f,0);var main=particles.main;main.maxParticles=1000;main.startLifetime=7;main.startSpeed=.12f;main.startSize=.018f;main.startColor=new Color(1,.78f,.87f,.7f);main.gravityModifier=.008f;var shape=particles.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(5,.1f,4);var emission=particles.emission;emission.rateOverTime=40;}
  void SetBackground(string path,string source){backdrop.Set(path,source);stage?.Dispose();stage=null;message="背景图片已替换舞台";}
  void ImportBackground(){string path=NativeDialogs.OpenImage();if(path==null)return;string name=Guid.NewGuid().ToString()+Path.GetExtension(path).ToLowerInvariant(),relative="backgrounds/"+name;string dest=Path.Combine(NativeAssets.Studio,"projects",relative);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(path,dest);SetBackground(dest,relative);}
  void SaveProject(){string path=NativeDialogs.Save("json","保存原生工程");if(path==null)return;var doc=new JObject{["format"]="227-native-project",["version"]=1,["frame"]=frame,["song"]=songIndex,["multi"]=multi,["hasMotion"]=actors.Any(a=>a?.motion!=null),["preset"]=preset,["backgroundImage"]=backdrop.source,["positions"]=new JArray(placements.Select(p=>new JArray(p.x,p.y,p.z))),["actors"]=new JArray(actors.Select(a=>a==null?null:new JObject{["character"]=a.character,["body"]=a.body})),["keys"]=new JObject(keys.Select(pair=>new JProperty(pair.Key,new JArray(pair.Value.Select(k=>new JObject{["frame"]=k.Key,["quaternion"]=new JArray(k.Value.x,k.Value.y,k.Value.z,k.Value.w)})))))};File.WriteAllText(path,doc.ToString());message="工程已保存";}
  void OpenProject(){string path=NativeDialogs.Open("json","打开原生工程");if(path==null)return;var doc=JObject.Parse(File.ReadAllText(path));if((string)doc["format"]!="227-native-project")throw new Exception("请选择原生桌面工程 JSON");NewProject();actors[2]?.Dispose();actors[2]=null;multi=(bool)doc["multi"];for(int i=0;i<5;i++)if(doc["actors"][i].Type!=JTokenType.Null){var a=doc["actors"][i];var person=people.Cast<JObject>().First(p=>(string)p["id"]==(string)a["character"]);actors[i]=new NativeActor(person,(string)a["body"],cloth);var p=doc["positions"][i];placements[i]=new Vector3((float)p[0],(float)p[1],(float)p[2]);}songIndex=(int)doc["song"];if((bool?)doc["hasMotion"]==true)LoadSong();frame=(float)doc["frame"];preset=(int)doc["preset"];Preset();foreach(var pair in (JObject)doc["keys"]){var track=new SortedDictionary<int,Quaternion>();foreach(var k in pair.Value){var q=k["quaternion"];track[(int)k["frame"]]=new Quaternion((float)q[0],(float)q[1],(float)q[2],(float)q[3]);}keys[pair.Key]=track;}string background=(string)doc["backgroundImage"];if(!string.IsNullOrEmpty(background)){string picturePath=background.StartsWith("/stages/")?NativeAssets.Local(background):Path.GetFullPath(Path.Combine(NativeAssets.Studio,"projects",background));if(!background.StartsWith("/stages/")&&!picturePath.StartsWith(Path.GetFullPath(Path.Combine(NativeAssets.Studio,"projects"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("背景资源路径不合法");SetBackground(picturePath,background);}message="原生工程已恢复";}
  void NewProject(){playing=false;audio.Stop();foreach(var actor in actors.Where(a=>a!=null))actor.Dispose();actors=new NativeActor[5];placements=new Vector3[5];stage?.Dispose();stage=null;backdrop.Clear();authored?.Dispose();authored=null;keys.Clear();frame=0;duration=300;selected=2;multi=false;ChoosePerson(0);}
  IEnumerator Screenshot(){string path=NativeDialogs.Save("png","保存视口图片");if(path==null)yield break;yield return new WaitForEndOfFrame();int width=camera.pixelWidth,height=camera.pixelHeight;var rt=new RenderTexture(width,height,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var captureRect=camera.rect;camera.rect=new Rect(0,0,1,1);camera.targetTexture=rt;backdrop.Refresh();camera.Render();RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;camera.rect=captureRect;Destroy(rt);Destroy(image);message="PNG 已保存";}
  IEnumerator Video(){string path=NativeDialogs.Save("mp4","导出固定帧率 MP4");if(path==null)yield break;busy=true;playing=false;audio.Pause();string temp=Path.Combine(NativeAssets.Studio,"cache/native-render",Guid.NewGuid().ToString());Directory.CreateDirectory(temp);var rt=new RenderTexture(1920,1080,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);camera.targetTexture=rt;float old=frame;try{int total=Mathf.FloorToInt(duration/30*60)+1;for(int i=0;i<total;i++){frame=i*.5f;Apply();foreach(var actor in actors.Where(a=>a!=null))foreach(var c in actor.cloth)c.ResetState();yield return new WaitForEndOfFrame();backdrop.Refresh();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(Path.Combine(temp,i.ToString("D7")+".png"),image.EncodeToPNG());message="原生逐帧导出 "+(i+1)+" / "+total;}string executable=Path.Combine(NativeAssets.Studio,"runtime/ffmpeg/ffmpeg.exe");string args="-y -framerate 60 -i \""+Path.Combine(temp,"%07d.png")+"\" -c:v h264_nvenc -pix_fmt yuv420p \""+path+"\"";var process=Process.Start(new ProcessStartInfo(executable,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true});var read=process.StandardError.ReadToEndAsync();while(!process.HasExited)yield return null;if(process.ExitCode!=0){args=args.Replace("h264_nvenc","libx264 -preset fast");process=Process.Start(new ProcessStartInfo(executable,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true});read=process.StandardError.ReadToEndAsync();while(!process.HasExited)yield return null;}message=process.ExitCode==0?"MP4 已导出（原生预览版暂不混音）":"编码失败";}finally{RenderTexture.active=null;camera.targetTexture=null;Destroy(rt);Destroy(image);frame=old;busy=false;}}
  IEnumerator CheckUpdate(){message="正在检查 GitHub…";using(var request=UnityWebRequest.Get("https://api.github.com/repos/Sora-Ayano/227-Motion-Studio/releases")){request.SetRequestHeader("User-Agent","227-Motion-Studio-Native");yield return request.SendWebRequest();if(request.result==UnityWebRequest.Result.Success){var release=JArray.Parse(request.downloadHandler.text).FirstOrDefault(r=>!(bool)r["draft"]&&((string)r["tag_name"]).StartsWith("v0.4"));message=release==null?"尚未发布新的原生版":"最新原生版："+(string)release["tag_name"];}else message="更新检查失败，可直接打开 Releases";}Application.OpenURL(Repo+"/releases");}
  IEnumerator Diagnostics(){yield return new WaitForSeconds(1);if(Environment.GetCommandLineArgs().Contains("--diagnostics-song")){outfitIndex=Enumerable.Range(0,outfits.Count).First(i=>OutfitID(i)=="120010100");ChoosePerson(0);multi=true;LoadSong();distance=5.5f;pitch=3;backdrop.Clear();stage=new NativeStage((string)stages[0]["url"]);cameraPreview=false;frame=300;playing=false;}yield return new WaitForSeconds(3);string dir=Path.Combine(NativeAssets.Studio,"cache/native-diagnostics");Directory.CreateDirectory(dir);var report=new JObject{["version"]=Version,["nativeRenderer"]=true,["gpu"]=SystemInfo.graphicsDeviceName,["backend"]=SystemInfo.graphicsDeviceType.ToString(),["compute"]=SystemInfo.supportsComputeShaders,["actors"]=actors.Count(a=>a!=null),["meshes"]=actors.Where(a=>a!=null).Sum(a=>a.meshes.Count),["clothFinite"]=actors.Where(a=>a!=null).SelectMany(a=>a.cloth).All(c=>c.Validate()),["stage"]=stage!=null};File.WriteAllText(Path.Combine(dir,"report.json"),report.ToString());yield return new WaitForEndOfFrame();var rt=new RenderTexture(1280,720,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.sRGB);var oldRect=camera.rect;camera.rect=new Rect(0,0,1,1);var captureRect=camera.rect;camera.rect=new Rect(0,0,1,1);camera.targetTexture=rt;backdrop.Refresh();camera.Render();RenderTexture.active=rt;var screenshot=new Texture2D(1280,720,TextureFormat.RGB24,false);screenshot.ReadPixels(new Rect(0,0,1280,720),0,0);screenshot.Apply();File.WriteAllBytes(Path.Combine(dir,"preview.png"),screenshot.EncodeToPNG());RenderTexture.active=null;camera.targetTexture=null;camera.rect=oldRect;Destroy(rt);Destroy(screenshot);yield return null;Application.Quit();}
